values ('dialog_fq_shard_072', 'fq_shard_072', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Peace be with you, Child. The Glowvine has been restless. The Aethel Iron Carapace creatures that have colonized the Prima Materia Fo...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions see the forest''s creatures as threats. They don''t understand. Every Shard-touched being was once a guardian. The Severance twisted their purpose — not erased it. We release them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Great Purification: Supply Line 04. In Aethel Siphon Core: Defeat 1 CRYSTAL_TYRANT. Do what must be done, then notice what the living place does in the silence afterward.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 681)
