values ('dialog_fq_shard_077', 'fq_shard_077', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "The Shard has whispered your name. Oracle Seraphel''s final vision before the Sanctum''s inner circle receives y...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Glowvine Forest sang before the Concordium''s first wall, before the Hegemony''s first weapon. Listen to its song — it guides where weapons and ledgers cannot.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Great Purification: Aethel Aftershock 04. In Eternal Gate: Defeat 1 GRAVITY_TITAN. Do what must be done, then notice what the living place does in the silence afterward.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 686)
