values ('dialog_fq_shard_088', 'fq_shard_088', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "The Shard has whispered your name. The Cradle Expanse''s purification continues", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard is not a weapon — it is a living memory of everything before the Severance. Billions of souls, a civilization, compressed into fragments. Shard-touched creatures are echoes.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Voice of the Shard: A Narrow Passage 05. In Eternal Gate: Defeat 1 ABYSS_HARBINGER. Do what must be done, then notice what the living place does in the silence afterward.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 697)
