insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_star_002', 'fq_star_002', 'npc_legion_class_trainer', 'greeting', '[{"id": "greeting", "text": "Legionnaire. We Hunt the Hunters — Sergeant Korg''s briefing is blunt in the way that experienced soldiers are ...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Legion''s history is written in blood of those before us. Every Legionnaire adds a chapter. Make yours worth reciting.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "A Place in the Sand: Broken Signal 01. In Dune Outskirts: Defeat 3 DUNE_SCAVENGER. Complete the task as assigned and report who stood beside you when the line held.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 711)
