values ('dialog_fq_star_007', 'fq_star_007', 'npc_legion_class_trainer', 'greeting', '[{"id": "greeting", "text": "The code demands action. Ash Hounds are fire given form and instinct", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Legion''s history is written in blood of those before us. Every Legionnaire adds a chapter. Make yours worth reciting.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "A Place in the Sand: Measure of Resolve 01. In Dune Outskirts: Defeat 3 FERAL_SAND_IMP. Complete the task as assigned and report who stood beside you when the line held.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 716)
